// Copies the shared assignment vectors generated by @splithub/core into the JVM tests:
// packages/core/test/vectors.json -> splithub-core/src/test/resources/vectors.json.
// Run from anywhere: `node sdks/android/scripts/copy-vectors.mjs`.
import { copyFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const from = resolve(here, '../../../packages/core/test/vectors.json');
const to = resolve(here, '../splithub-core/src/test/resources/vectors.json');

if (!existsSync(from)) {
  console.error(`No vectors at ${from}. Generate them first: cd packages/core && npx tsup && node scripts/vectors.mjs`);
  process.exit(1);
}
mkdirSync(dirname(to), { recursive: true });
copyFileSync(from, to);
console.log(`copied ${from} -> ${to}`);
